import { defineVaporComponent, VaporFor } from 'vue-jsx-vapor';

const Status__static1 = <p>none</p>;
const Status__static2 = <p>some</p>;
const Status__static3 = <p>many</p>;
const Status__static4 = <li>empty</li>;

export const Status = defineVaporComponent(function Status(
	{ count, items, mode }: { 
		count: number;
		items: { id: number; text: string }[];
		mode: string
	 }
) {
	return <section>{count > 2
			? Status__static3
			: count > 0 ? Status__static2 : Status__static1}<ul>{items.length === 0
				? (() => {
					return Status__static4;
				})()
				: items.map((item, i) => {
					return <li key={item.id}>{i}: {item.text}</li>;
				})}</ul><ol>{<VaporFor in={items}>{(item) => <li>{item.text}</li>}</VaporFor>}</ol>{(() => {
			switch (mode) {
				case 'a':
					return <b>a</b>;

				case 'b':
					return <i>b</i>;

				default:
					return <u>other</u>;
			}

			return null;
		})()}</section>;
});

